if(!text.includes('\n') && text.length>215){
  // Break at sentence boundaries only. Preserve sentence order and every word.
  const parts=text.split(/(?<=[.!?])\s+(?=[A-ZÀ-Ý])/u);
  if(parts.length>=3){
    const groups=[];let group='';
    for(const part of parts){
      if(group && group.length+part.length>185){groups.push(group);group=part;}
      else group=group?group+' '+part:part;
    }
    if(group)groups.push(group);
    if(groups.length>1)formatted=groups.join('\n\n');
  }
}
